<div class="mb-5 flex items-center justify-between"><p class="text-sm text-slate-500"><?=count($categories)?> categorias cadastradas</p><a class="btn btn-primary" href="<?=url('categories/form')?>"><i data-lucide="plus"></i>Nova categoria</a></div>
